  assign m[1  ] = (tr_ir & 16'hFE00) == 16'h0200;   // SUB
  assign m[2  ] = (tr_ir & 16'hFE00) == 16'h0400;   // AND
  assign m[3  ] = (tr_ir & 16'hFE00) == 16'h0600;   // OR
  assign m[4  ] = (tr_ir & 16'hFE00) == 16'h0800;   // XOR
  assign m[5  ] = (tr_ir & 16'hFE00) == 16'h0A00;   // SHL
  assign m[6  ] = (tr_ir & 16'hFE00) == 16'h0C00;   // SHR
  assign m[7  ] = (tr_ir & 16'hFE00) == 16'h0E00;   // ROR
  assign m[8  ] = (tr_ir & 16'hFE00) == 16'h1000;   // ADDI
  assign m[9  ] = (tr_ir & 16'hFE00) == 16'h1200;   // SUBI
  assign m[10 ] = (tr_ir & 16'hFE00) == 16'h1400;   // ANDI
  assign m[11 ] = (tr_ir & 16'hFE00) == 16'h1600;   // ORI
  assign m[12 ] = (tr_ir & 16'hFE00) == 16'h1800;   // XORI
  assign m[13 ] = (tr_ir & 16'hFE00) == 16'h1A00;   // SHLI
  assign m[14 ] = (tr_ir & 16'hFE00) == 16'h1C00;   // SHRI
  assign m[15 ] = (tr_ir & 16'hFE00) == 16'h1E00;   // CMPI
  assign m[16 ] = (tr_ir & 16'hF800) == 16'h2000;   // LDI
  assign m[17 ] = (tr_ir & 16'hF800) == 16'h2800;   // LDIH
  assign m[18 ] = (tr_ir & 16'hFE00) == 16'h3000;   // MOV
  assign m[19 ] = (tr_ir & 16'hFE00) == 16'h3200;   // NOT
  assign m[20 ] = (tr_ir & 16'hFE00) == 16'h3400;   // NEG
  assign m[21 ] = (tr_ir & 16'hFE00) == 16'h3600;   // CMP
  assign m[22 ] = (tr_ir & 16'hFE00) == 16'h3800;   // TEST
  assign m[23 ] = (tr_ir & 16'hFE00) == 16'h3A00;   // REV
  assign m[24 ] = (tr_ir & 16'hFE00) == 16'h3C00;   // PAR
  assign m[25 ] = (tr_ir & 16'hFE00) == 16'h3E00;   // SWAP
  assign m[26 ] = (tr_ir & 16'hFC00) == 16'h4000;   // JMP
  assign m[27 ] = (tr_ir & 16'hFC00) == 16'h4400;   // CALL
  assign m[28 ] = (tr_ir & 16'hFC00) == 16'h4800;   // RET
  assign m[29 ] = (tr_ir & 16'hFC00) == 16'h4C00;   // HALT
  assign m[30 ] = (tr_ir & 16'hFF00) == 16'h5000;   // BZ
  assign m[31 ] = (tr_ir & 16'hFF00) == 16'h5200;   // BNZ
  assign m[32 ] = (tr_ir & 16'hFF00) == 16'h5400;   // BC
  assign m[33 ] = (tr_ir & 16'hFF00) == 16'h5600;   // BNC
  assign m[34 ] = (tr_ir & 16'hFF00) == 16'h5800;   // BT
  assign m[35 ] = (tr_ir & 16'hFF00) == 16'h5A00;   // BNT
  assign m[36 ] = (tr_ir & 16'hF800) == 16'h6000;   // DJNZ
  assign m[37 ] = (tr_ir & 16'hF000) == 16'h7000;   // JP
  assign m[38 ] = (tr_ir & 16'hFC00) == 16'h8000;   // SETP
  assign m[39 ] = (tr_ir & 16'hFC00) == 16'h8400;   // OEP
  assign m[40 ] = (tr_ir & 16'hFC00) == 16'h8800;   // OUT
  assign m[41 ] = (tr_ir & 16'hFC00) == 16'h8C00;   // IN
  assign m[42 ] = (tr_ir & 16'hFE00) == 16'h9000;   // WAITD
  assign m[43 ] = (tr_ir & 16'hFE00) == 16'h9200;   // WAITP
  assign m[44 ] = (tr_ir & 16'hFE00) == 16'h9400;   // WAITE
  assign m[45 ] = (tr_ir & 16'hFE00) == 16'h9600;   // WAITS
