  assign m[47 ] = (tr_ir & 16'hFE00) == 16'h9A00;   // DLY
  assign m[48 ] = (tr_ir & 16'hFE00) == 16'h9C00;   // SETD
  assign m[49 ] = (tr_ir & 16'hFE00) == 16'h9E00;   // NOP
