  assign m[53 ] = (tr_ir & 16'hFF80) == 16'hA480;   // SHI
  assign m[54 ] = (tr_ir & 16'hFF80) == 16'hA800;   // LDSR
  assign m[55 ] = (tr_ir & 16'hFF80) == 16'hA880;   // STSR
  assign m[56 ] = (tr_ir & 16'hFF80) == 16'hAC00;   // CRCI
  assign m[57 ] = (tr_ir & 16'hFF80) == 16'hAC80;   // STCRC
  assign m[58 ] = (tr_ir & 16'hF800) == 16'hB000;   // CSRR
  assign m[59 ] = (tr_ir & 16'hF800) == 16'hB800;   // CSRW
  assign m[60 ] = (tr_ir & 16'hF800) == 16'hC000;   // CLR
  assign m[61 ] = (tr_ir & 16'hF800) == 16'hC800;   // SIG
  assign m[62 ] = (tr_ir & 16'hF800) == 16'hD000;   // LD
  assign m[63 ] = (tr_ir & 16'hF800) == 16'hD800;   // ST
  // SEMANTICS 6.11: the completion slot of an LD/ST decodes nothing; the
  // word it carries is data, so a reserved-looking one is not a reserved
  // instruction. Before slice B every valid slot decoded its word.
  wire f_reserved = (m == 64'd0) && !w_mem_done;

  wire [9:0] f_next = tr_pc + 10'd1;      // SEMANTICS 6: next = (PC + 1) mod 2^10

  reg        p_valid, p_reserved;
  reg [1:0]  p_thread;
  reg [2:0]  p_flags;
  reg        p_rst_n;
  always @(posedge clk) begin
    p_valid    <= tr_valid;
    p_reserved <= f_reserved;
    p_thread   <= tr_thread;
    p_flags    <= tr_flags;
    p_rst_n    <= rst_n;
  end

  // ================================================================
  // ISA-2A: a reserved word retires as a NOP: one slot (`done`), no
  // register write, PC <= next.
